fn length(xs: List[Int]) -> Int
  ensures result == len(xs)
  effects pure
  example length([5, 1, 3]) == 3
  example length([]) == 0
{
  match xs {
    [] => 0
    [_, ..t] => 1 + length(t)
  }
}

fn min_of(xs: List[Int]) -> Int
  requires len(xs) > 0
  ensures contains(xs, result)
  ensures forall x in xs: result <= x
  effects pure
  example min_of([5, 1, 3]) == 1
  example min_of([8]) == 8
{
  match xs {
    [] => 0
    [h, ..t] => match t {
      [] => h
      _ => if h <= min_of(t) then h else min_of(t)
    }
  }
}

fn remove_val(xs: List[Int], v: Int) -> List[Int]
  requires distinct(xs)
  ensures len(result) == len(xs) - count(xs, v)
  ensures not contains(result, v)
  effects pure
  example remove_val([5, 1, 3], 1) == [5, 3]
  example remove_val([5, 1, 3], 7) == [5, 1, 3]
{
  match xs {
    [] => []
    [h, ..t] => if h == v then t else [h] ++ remove_val(t, v)
  }
}

fn pick(xs: List[Int], k: Int) -> Int
  requires distinct(xs) and k >= 0 and k < len(xs)
  ensures contains(xs, result)
  ensures (count x in xs: x < result) == k
  effects pure
  example pick([5, 1, 3], 0) == 1
  example pick([5, 1, 3], 1) == 3
  example pick([5, 1, 3], 2) == 5
{
  if k == 0 then min_of(xs) else pick(remove_val(xs, min_of(xs)), k - 1)
}

fn median_odd(xs: List[Int]) -> Int
  requires len(xs) % 2 == 1
  requires distinct(xs)
  ensures contains(xs, result)
  ensures (count x in xs: x < result) == len(xs) / 2
  effects pure
  example median_odd([5, 1, 3]) == 3
  example median_odd([8]) == 8
  example median_odd([9, 4, 7, 2, 6]) == 6
{
  pick(xs, length(xs) / 2)
}

